/**
 * The last local check before an EIP-3009 authorization is signed: does the
 * paying wallet actually hold what the challenge asks for?
 *
 * Without it, a wallet with no USDC signs a valid authorization, ships it in
 * `X-PAYMENT`, and the facilitator broadcasts a `transferWithAuthorization`
 * that reverts at the token's balance check. What comes back is a generic
 * `settle_failed` from the server — see `gateway/src/server.ts` — which says
 * nothing about the one thing that was wrong and which the client already had
 * everything it needed to know. Worse, the revert burns the SPONSOR's gas: an
 * unfunded caller costs the operator money on every attempt.
 *
 * So the balance is read here, locally, and a shortfall becomes a coded
 * failure carrying the remedy. Nothing is signed and nothing goes on the wire.
 */
import type { Address } from 'viem';
import { type NetworkSlug } from '../chains.js';
import { BuyError } from '../errors.js';
/** An accepted token the wallet already covers, named in the shortfall error. */
type CoveredAlternative = {
    symbol: string;
    asset: Address;
    balance: bigint;
    decimals: number;
};
/**
 * Reads an ERC-20 balance. Injected rather than imported so the check has a
 * seam — `@celo/buy-core`'s own `getTokenBalance` is the production one.
 */
export type BalanceReader = (args: {
    network: NetworkSlug;
    token: Address;
    owner: Address;
}) => Promise<bigint>;
/**
 * Throw `insufficient_balance` when `owner` cannot cover `required` of `asset`.
 *
 * FAILS OPEN. If the read itself throws — a rate-limited RPC, a node that is
 * down, a token that answers `balanceOf` with something undecodable — the
 * payment proceeds exactly as it did before this check existed. That direction
 * is deliberate: this is a better error message, not a safety control. The
 * settlement path already refuses an underfunded payment on-chain, so a
 * failing pre-flight that BLOCKED would trade a clear on-chain rejection for
 * an outage in which nobody can pay at all.
 */
export declare function assertSufficientBalance(opts: {
    network: NetworkSlug;
    /** Token address from the 402 challenge — not necessarily a registry token. */
    asset: Address;
    /** Atomic units the challenge demands. */
    required: bigint;
    /** The wallet that would sign. */
    owner: Address;
    read: BalanceReader;
    /**
     * The OTHER offers the same 402 accepts, each with its raw atomic amount as a
     * string. When the selected token is short, these are probed so the error can
     * name one the wallet already covers, instead of sending an agent to fund a
     * token it does not need. Raw strings, not bigints: a malformed amount on an
     * offer the wallet is not even paying with must not throw on the success path,
     * so parsing is deferred and defensive. Absent or empty: the plain fund-it
     * remedy.
     *
     * Passed only for a 402 payment (`buy curl`, `payingFetch`), never by `buy
     * send`, so its presence is also what says the starter-faucet hint applies.
     */
    alternatives?: Array<{
        asset: Address;
        required: string;
    }>;
}): Promise<void>;
/**
 * The failure, built in one place so `payingFetch` and `buy curl` — which
 * re-implements the same local checks against real `curl` — cannot drift into
 * reporting the same condition two different ways.
 */
export declare function insufficientBalanceError(opts: {
    network: NetworkSlug;
    asset: Address;
    required: bigint;
    owner: Address;
    balance: bigint;
    /** An accepted token the wallet already covers, if one was found. */
    covered?: CoveredAlternative;
    /**
     * Every token the 402 accepts, for a payment from a wallet that holds none of
     * them; absent for `buy send` and for a wallet that is short rather than empty.
     */
    offered?: Address[];
}): BuyError;
export {};
